basicCode.vanilla:
import { createComposer } from '@/components/ui/composer';

createComposer({
  labels,
  quoteLabels,
  quote: { id: 'm-7', author: 'Ana Souza', excerpt: texto },
  onDismissQuote: () => responder(null),
});

basicCode.react:
import { Composer } from "@/components/ui/composer";

<Composer
  labels={labels}
  quoteLabels={quoteLabels}
  quote={{ id: "m-7", author: "Ana Souza", excerpt: texto }}
  onDismissQuote={() => responder(null)}
/>

fromThreadCode.web:
// A citação vem da thread, e o `id` é o mesmo endereço que a mensagem tem
// lá — é ele que diz a quem a resposta responde.
{
  id: mensagem.id,
  author: mensagem.author,
  role: mensagem.role,     // o mesmo vocabulário do chat-protocol
  excerpt: mensagem.content,  // INTEIRO: quem corta é a folha, por linha
}

extensibilityCode.web:
// O trecho vai INTEIRO. Cortar aqui apagaria o resto para quem lê por
// audição, que não tem "linhas" — tem o texto.
{ author: 'Ana Souza', excerpt: mensagemInteira }

// E não corte no servidor tampouco: a busca do navegador procura no que está
// no documento, e o que foi cortado não está.

customizationCode.web:
.nds-composer-quote {
  border-inline-start-color: hsl(var(--primary));
}

/* O corte é por LINHA, e é aqui que se decide quantas. Cortar por caractere
   em código apagaria o resto do texto para quem lê por audição. */
.nds-composer-quote-excerpt {
  -webkit-line-clamp: 3;
}

